@rule("s2", "s22", otherwise="Contradiction")
def check_reverse_engineering():
    return "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." == "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information."

@rule("s3", "s22", otherwise="Contradiction")
def check_reverse_engineering_confidentiality():
    return "Recipient will not reverse engineer, create other works from, or disassemble any software programs contained in the CI without Discloser’s prior written consent." == "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information."

@rule("s4", "s22", otherwise="Contradiction")
def check_reverse_engineering_rights():
    return "Recipient does not receive any license or intellectual property rights to Discloser’s CI." == "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information."

query = "Entailment" if check_reverse_engineering() and check_reverse_engineering_confidentiality() and check_reverse_engineering_rights() else "Contradiction" if not (check_reverse_engineering() and check_reverse_engineering_confidentiality() and check_reverse_engineering_rights()) else "NotMentioned"
